import{_ as a,o as n,a as p,b as c}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"L1/L0C与UB数据搬运","link":"/api/SIMD-API/c_api/data_move_guide/l1_or_l0c_ub_data_move"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/l1_or_l0c_ub_data_move.md","filePath":"api/SIMD-API/c_api/data_move_guide/l1_or_l0c_ub_data_move.md","outlineHeaders":[{"level":2,"title":"总体说明","slug":"总体说明","link":"#总体说明"},{"level":2,"title":"asc_copy_ub2l1（UB到L1连续数据搬运）","slug":"asc_copy_ub2l1（UB到L1连续数据搬运）","link":"#asc_copy_ub2l1（UB到L1连续数据搬运）"},{"level":2,"title":"asc_copy_ub2l1（UB到L1高维切分数据搬运）","slug":"asc_copy_ub2l1（UB到L1高维切分数据搬运）","link":"#asc_copy_ub2l1（UB到L1高维切分数据搬运）"},{"level":2,"title":"asc_copy_l12ub（L1到UB数据搬运）","slug":"asc_copy_l12ub（L1到UB数据搬运）","link":"#asc_copy_l12ub（L1到UB数据搬运）"},{"level":2,"title":"asc_copy_l0c2ub（L0C到UB随路处理搬运）","slug":"asc_copy_l0c2ub（L0C到UB随路处理搬运）","link":"#asc_copy_l0c2ub（L0C到UB随路处理搬运）"},{"level":3,"title":"目的AIV选择","slug":"目的AIV选择","link":"#目的AIV选择"},{"level":3,"title":"格式、量化与激活","slug":"格式、量化与激活","link":"#格式、量化与激活"},{"level":3,"title":"步长与边界","slug":"步长与边界","link":"#步长与边界"},{"level":2,"title":"同步要求","slug":"同步要求","link":"#同步要求"}],"lastUpdated":1790563388000}'),l={name:"api/SIMD-API/c_api/data_move_guide/l1_or_l0c_ub_data_move.md"};function t(_,s,e,d,o,i){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>L1/L0C与UB数据搬运</h1><p>NPU架构版本3510支持L1到UB、UB到L1以及L0C到UB三条片上通路，用于在Cube侧和Vector侧之间交换输入或中间结果。三条通路均为单向通路，分别属于PIPE_MTE1、PIPE_MTE3和PIPE_FIX；NPU架构版本3510不提供UB到L0C的通用搬运。</p><h2 id="总体说明">总体说明<a class="header-anchor" href="#总体说明">​</a></h2><table><thead><tr><th>方向</th><th>搬运模式</th><th>接口</th><th>流水</th><th>执行范围</th></tr></thead><tbody><tr><td>UB到L1</td><td>连续</td><td><a href="../vector_datamove/asc_copy_ub2l1.html">asc_copy_ub2l1</a></td><td>PIPE_MTE3</td><td>AIV</td></tr><tr><td>UB到L1</td><td>高维切分</td><td><a href="../vector_datamove/asc_copy_ub2l1.html">asc_copy_ub2l1</a></td><td>PIPE_MTE3</td><td>AIV</td></tr><tr><td>L1到UB</td><td>连续</td><td><a href="../cube_datamove/asc_copy_l12ub.html">asc_copy_l12ub</a></td><td>PIPE_MTE1</td><td>AIC</td></tr><tr><td>L1到UB</td><td>高维切分</td><td><a href="../cube_datamove/asc_copy_l12ub.html">asc_copy_l12ub</a></td><td>PIPE_MTE1</td><td>AIC</td></tr><tr><td>L0C到UB</td><td>搬出矩阵结果，可组合量化、激活、格式转换或双目标写入</td><td><a href="../cube_datamove/asc_copy_l0c2ub.html">asc_copy_l0c2ub</a></td><td>PIPE_FIX</td><td>AIC</td></tr></tbody></table><h2 id="asc_copy_ub2l1（UB到L1连续数据搬运）">asc_copy_ub2l1（UB到L1连续数据搬运）<a class="header-anchor" href="#asc_copy_ub2l1（UB到L1连续数据搬运）">​</a></h2><p>连续模式按<code>size</code>指定的字节数从UB搬到L1，数据格式和内容保持不变。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_ub2l1</span><span class="p">(</span><span class="n">__cbuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">size</span><span class="p">)</span>
</code></pre></div><ul><li>源UB和目的L1地址均需要32字节对齐。</li><li><code>size</code>单位为字节，取值范围为[32, 4095×32]，并且需要是32的整数倍。</li><li><code>size</code>不对齐时，硬件按<code>size / 32</code>截断，多出的字节不会搬运。</li></ul><h2 id="asc_copy_ub2l1（UB到L1高维切分数据搬运）">asc_copy_ub2l1（UB到L1高维切分数据搬运）<a class="header-anchor" href="#asc_copy_ub2l1（UB到L1高维切分数据搬运）">​</a></h2><p>高维切分模式通过数据块个数、每块长度以及源、目的块间间隔描述非连续排布。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_ub2l1</span><span class="p">(</span><span class="n">__cbuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">burst_count</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">burst_len</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_gap</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap</span><span class="p">)</span>
</code></pre></div><ul><li><code>burst_len</code>以32字节DataBlock为单位。</li><li><code>src_gap</code>和<code>dst_gap</code>表示前一数据块结束地址到下一数据块起始地址之间的间隔，也以DataBlock为单位。</li><li><code>burst_count</code>为1时，两个间隔可设为0；多块搬运时，源、目的最大访问跨度均需要计入块间间隔。</li></ul><h2 id="asc_copy_l12ub（L1到UB数据搬运）">asc_copy_l12ub（L1到UB数据搬运）<a class="header-anchor" href="#asc_copy_l12ub（L1到UB数据搬运）">​</a></h2><p>该接口从AIC发射，把L1数据写入指定AIV的UB。通过<code>burst_count</code>、<code>burst_len</code>、<code>src_gap</code>和<code>dst_gap</code>描述高维切分排布；连续场景可配置一个数据块，或令多个数据块的间隔为0。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12ub</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">dst_addr</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__cbuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">src_addr</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">int8_t</span><span class="w"> </span><span class="n">sub_blockid</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">burst_count</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">burst_len</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_gap</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap</span><span class="p">)</span>
</code></pre></div><ul><li><code>src_addr</code>和<code>dst_addr</code>均需要32字节对齐。</li><li><code>sub_blockid</code>为0时写入AIV0的UB，为1时写入AIV1的UB。</li><li><code>burst_len</code>、<code>src_gap</code>和<code>dst_gap</code>均以32字节为单位；<code>src_gap</code>和<code>dst_gap</code>表示数据块之间的空隙，而不是相邻块首地址间距。</li><li>L1容量上限为512KB；UB名义容量为256KB，但实际可用空间需要扣除SIMD VF栈、预留空间和可能启用的SIMT Data Cache。</li></ul><h2 id="asc_copy_l0c2ub（L0C到UB随路处理搬运）">asc_copy_l0c2ub（L0C到UB随路处理搬运）<a class="header-anchor" href="#asc_copy_l0c2ub（L0C到UB随路处理搬运）">​</a></h2><p>该接口将Cube计算结果直接写入一个或两个AIV的UB，可在PIPE_FIX中组合类型转换、量化、激活和格式转换。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l0c2ub</span><span class="p">(</span><span class="n">__ubuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dst_dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                       </span><span class="n">__cc__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">src_dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">n_size</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">m_size</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dst_stride</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">int8_t</span><span class="w"> </span><span class="n">sub_blockid</span><span class="p">,</span>
<span class="w">                                       </span><span class="n">asc_dual_dst_mode</span><span class="w"> </span><span class="n">dual_dst_ctrl</span><span class="p">,</span>
<span class="w">                                       </span><span class="n">asc_unit_flag_mode</span><span class="w"> </span><span class="n">unit_flag_mode</span><span class="p">,</span>
<span class="w">                                       </span><span class="n">asc_quant_mode</span><span class="w"> </span><span class="n">quant_pre_mode</span><span class="p">,</span>
<span class="w">                                       </span><span class="n">asc_relu_pre_mode</span><span class="w"> </span><span class="n">relu_pre_mode</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">bool</span><span class="w"> </span><span class="n">enable_channel_split</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">bool</span><span class="w"> </span><span class="n">enable_nz2nd</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">bool</span><span class="w"> </span><span class="n">enable_nz2dn</span><span class="p">,</span>
<span class="w">                                       </span><span class="kt">bool</span><span class="w"> </span><span class="n">enable_clip_relu_pre</span><span class="p">)</span>
</code></pre></div><h3 id="目的AIV选择">目的AIV选择<a class="header-anchor" href="#目的AIV选择">​</a></h3><ul><li>单目标模式下，<code>sub_blockid</code>选择AIV0或AIV1，完整矩阵写入对应UB。</li><li><code>asc_dual_dst_mode::DUAL_DST_SPLIT_M</code>按M维把矩阵一分为二，分别写入两个UB，M需要是2的倍数。</li><li><code>asc_dual_dst_mode::DUAL_DST_SPLIT_N</code>按N维拆分，N需要是32的倍数。</li><li>双目标仅支持普通Nz2Nz或Nz2ND场景，不能与其他随路能力任意组合。</li></ul><h3 id="格式、量化与激活">格式、量化与激活<a class="header-anchor" href="#格式、量化与激活">​</a></h3><table><thead><tr><th>功能</th><th>主接口参数</th><th>前置配置</th></tr></thead><tbody><tr><td>Nz2ND</td><td><code>enable_nz2nd</code></td><td><a href="../cube_datamove/asc_set_l0c_copy_nz_para.html">asc_set_l0c_copy_nz_para</a></td></tr><tr><td>Nz2DN</td><td><code>enable_nz2dn</code></td><td><code>asc_set_l0c_copy_nz_para</code>、<a href="../cube_datamove/asc_set_l0c_copy_channel_para.html">asc_set_l0c_copy_channel_para</a></td></tr><tr><td>scalar量化</td><td><code>quant_pre_mode</code></td><td><a href="../cube_datamove/asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant</a></td></tr><tr><td>tensor量化</td><td><code>quant_pre_mode</code></td><td><a href="../cube_datamove/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a></td></tr><tr><td>ReLU/Leaky ReLU</td><td><code>relu_pre_mode</code>、<code>enable_clip_relu_pre</code></td><td><a href="../cube_datamove/asc_set_l0c_copy_relu_alpha.html">asc_set_l0c_copy_relu_alpha</a>、<a href="../cube_datamove/asc_set_l0c_copy_lrelu_alpha.html">asc_set_l0c_copy_lrelu_alpha</a></td></tr></tbody></table><p><code>src_dtype</code>为<code>int32_t</code>或<code>float</code>，目的类型由量化或Cast模式决定。源、目的数据类型必须与<code>quant_pre_mode</code>匹配，量化系数不能为INF、NAN或非规格化数。</p><h3 id="步长与边界">步长与边界<a class="header-anchor" href="#步长与边界">​</a></h3><ul><li>源L0C地址需要64字节对齐，目的UB地址需要32字节对齐。</li><li><code>src_stride</code>以64字节为单位，表示源Nz矩阵相邻Z排布起始地址的距离。</li><li><code>dst_stride</code>以元素为单位；Nz输出时表示相邻Z排布间距，ND/DN输出时表示一行的元素数，对应字节长度需要32字节对齐。</li><li>L0C和UB访问范围分别不能超过256KB和实际分配的UB空间。双目标模式需要分别检查两个AIV的目的范围。</li></ul><h2 id="同步要求">同步要求<a class="header-anchor" href="#同步要求">​</a></h2><ul><li>AIV通过PIPE_MTE3把UB写入L1后，AIC读取L1前需要完成AIV到AIC的核间同步并建立后续流水依赖。AIC依赖同一group内全部AIV时，使用模式2的<a href="../sync/inter_core_sync/asc_sync_block_arrive.html">asc_sync_block_arrive</a>和<a href="../sync/inter_core_sync/asc_sync_block_wait.html">asc_sync_block_wait</a>，由各AIV发送通知、AIC等待；仅依赖单个AIV时，使用模式4的<a href="../sync/inter_core_sync/asc_sync_intra_arrive.html">asc_sync_intra_arrive</a>和<a href="../sync/inter_core_sync/asc_sync_intra_wait.html">asc_sync_intra_wait</a>。</li><li>AIC通过PIPE_MTE1把L1写入UB，或通过PIPE_FIX把L0C写入UB后，AIV读取UB前需要完成AIC到目标AIV的同步。全部AIV均消费数据时使用模式2，由AIC发送通知、各AIV等待；仅指定AIV消费数据时使用模式4。</li><li>L0C由PIPE_M生成，PIPE_FIX搬出前需要同步；满足条件时也可通过UnitFlag让矩阵计算和搬出按分形并行。</li><li>多条指令写入相同L1或UB范围时，需要按<a href="../sync/system_sync_overview.html">同步控制</a>要求串行化，不能仅依赖源码顺序。</li></ul></article></div>`,1)])])}const u=a(l,[["render",t]]);export{h as __pageData,u as default};
